using System.Reflection;
using Microsoft.Extensions.Configuration;
using Xunit.Sdk;

namespace TutorFlow.Api.Tests.Operacion;

internal static class ValidadorPendiente
{
    private const string NombreDelTipo = "TutorFlow.Api.ValidadorDeConfiguracion";
    private const string NombreDelMetodo = "Validar";

    public static IReadOnlyList<string> Validar(IConfiguration configuracion)
    {
        var metodo = typeof(Program).Assembly.GetType(NombreDelTipo)?.GetMethod(
            NombreDelMetodo,
            BindingFlags.Public | BindingFlags.Static,
            [typeof(IConfiguration)])
            ?? throw new XunitException(
                $"falta la clase estática pública {NombreDelTipo} con 'public static IReadOnlyList<string> {NombreDelMetodo}(IConfiguration configuracion)' (spec 001 §11.4, ESC-181 af)");
        return (IReadOnlyList<string>)metodo.Invoke(null, [configuracion])!;
    }
}
using TutorFlow.Core.Asistente;

namespace TutorFlow.Api.Tests;

public static class AfirmacionesDeReintento
{
    private const string PropiedadDeAuditoria = "Reintento";

    public static bool ReintentoRegistrado(EventoAuditoria evento) =>
        typeof(EventoAuditoria).GetProperty(PropiedadDeAuditoria)?.GetValue(evento) is true;

    public static void AfirmarReintentoRegistrado(EventoAuditoria evento)
    {
        var propiedad = typeof(EventoAuditoria).GetProperty(PropiedadDeAuditoria);
        Assert.True(propiedad is not null, "EventoAuditoria no define Reintento (spec 001 §7.3 'Auditoría', D-48): se espera bool Reintento { get; init; }.");
        Assert.True(propiedad.GetValue(evento) is true, "el evento debía llevar reintento: true");
    }
}
using TutorFlow.Core.Asistente;
using static TutorFlow.Core.Tests.Asistente.EscenarioAsistente;

namespace TutorFlow.Core.Tests.Asistente;

internal sealed record MensajeCapturado(RolMensaje Rol, string Contenido);

internal sealed class GuionDeDosTurnos(string primerTurno, string reintento, bool leePrograma = false)
{
    public List<IReadOnlyList<MensajeCapturado>> Capturas { get; } = [];

    public RespuestaLlm Responder(SolicitudLlm solicitud, int llamada)
    {
        Capturas.Add([.. solicitud.Mensajes.Select(m => new MensajeCapturado(m.Rol, m.Contenido))]);
        if (ReintentoDeLlm.EsReintento(solicitud))
        {
            return Texto(reintento);
        }

        return leePrograma && !solicitud.Mensajes.Any(m => m.Rol == RolMensaje.Herramienta)
            ? Herramienta(HerramientasAsistente.Programa)
            : Texto(primerTurno);
    }
}

internal static class ReintentoDeLlm
{
    public const string Prefijo = "Tu respuesta anterior no se pudo verificar: ";
    private const string PropiedadDeAuditoria = "Reintento";

    public static string Instruccion(string motivo) =>
        $"{Prefijo}{motivo}. Responde de nuevo usando solo los datos y las secciones entregados.";

    public static bool EsReintento(SolicitudLlm solicitud) =>
        solicitud.Mensajes.Any(m => m.Rol == RolMensaje.Usuario && m.Contenido.StartsWith(Prefijo, StringComparison.Ordinal));

    public static IReadOnlyList<SolicitudLlm> Reintentos(LlmDoble llm) => [.. llm.Solicitudes.Where(EsReintento)];

    public static bool ReintentoRegistrado(EventoAuditoria evento) =>
        typeof(EventoAuditoria).GetProperty(PropiedadDeAuditoria)?.GetValue(evento) is true;

    public static void AfirmarReintentoRegistrado(EventoAuditoria evento)
    {
        var propiedad = typeof(EventoAuditoria).GetProperty(PropiedadDeAuditoria);
        Assert.True(propiedad is not null, "EventoAuditoria no define Reintento (spec 001 §7.3 'Auditoría', D-48): se espera bool Reintento { get; init; }.");
        Assert.True(propiedad.GetValue(evento) is true, "el evento debía llevar reintento: true");
    }

    public static void AfirmarSegundoTurno(GuionDeDosTurnos guion, string primeraRespuesta, string instruccion)
    {
        Assert.True(guion.Capturas.Count >= 2, "el modelo debía recibir al menos 2 llamadas");
        var reintento = guion.Capturas[^1];
        var previa = guion.Capturas[^2];
        Assert.Equal(previa.Count + 2, reintento.Count);
        Assert.Equal(previa, reintento.Take(previa.Count));
        Assert.Equal(new MensajeCapturado(RolMensaje.Asistente, primeraRespuesta), reintento[^2]);
        Assert.Equal(new MensajeCapturado(RolMensaje.Usuario, instruccion), reintento[^1]);
        Assert.Single(guion.Capturas, c => c.Any(m => m.Contenido.StartsWith(Prefijo, StringComparison.Ordinal)));
    }
}
using TutorFlow.Core.Asistente;

namespace TutorFlow.Pruebas.Soporte;

public static class ResultadosNuevosDeAuditoria
{
    public static ResultadoAuditoria EstadoNoVerificado =>
        Enum.TryParse<ResultadoAuditoria>("EstadoNoVerificado", out var resultado)
            ? resultado
            : throw new InvalidOperationException("ResultadoAuditoria no define EstadoNoVerificado (estado_no_verificado, spec 001 §11.3).");
}
using System.Text.RegularExpressions;
using TutorFlow.Core.Autorizacion;

namespace TutorFlow.Pruebas.Soporte;

public static partial class PartesDelPrompt
{
    public static string Ejemplos(string prompt)
    {
        var bloque = BloqueDeEjemplos().Match(prompt);
        return bloque.Success
            ? bloque.Groups["cuerpo"].Value
            : throw new InvalidOperationException("El prompt de sistema no tiene el bloque <ejemplos>...</ejemplos>.");
    }

    public static string Instrucciones(string prompt) => BloqueDeEjemplos().Replace(prompt, string.Empty);

    public static IReadOnlyList<string> CasosDeEjemplo(string prompt) =>
        [.. CasoDeEjemplo().Matches(Ejemplos(prompt)).Select(caso => caso.Groups["cuerpo"].Value)];

    public static string[] Palabras(string texto) =>
        NormalizadorTexto.Normalizar(texto).Split(' ', StringSplitOptions.RemoveEmptyEntries);

    public static string PrimerasPalabras(string texto, int cantidad) =>
        string.Join(' ', Palabras(texto).Take(cantidad));

    public static HashSet<string> Fragmentos(string texto, int palabrasPorFragmento)
    {
        var palabras = Palabras(texto);
        return Enumerable.Range(0, Math.Max(0, palabras.Length - palabrasPorFragmento + 1))
            .Select(inicio => string.Join(' ', palabras[inicio..(inicio + palabrasPorFragmento)]))
            .ToHashSet(StringComparer.Ordinal);
    }

    [GeneratedRegex("<ejemplos>(?<cuerpo>.*?)</ejemplos>", RegexOptions.Singleline | RegexOptions.CultureInvariant, matchTimeoutMilliseconds: 1000)]
    private static partial Regex BloqueDeEjemplos();

    [GeneratedRegex("<ejemplo>(?<cuerpo>.*?)</ejemplo>", RegexOptions.Singleline | RegexOptions.CultureInvariant, matchTimeoutMilliseconds: 1000)]
    private static partial Regex CasoDeEjemplo();
}

