        "cual es el promedio de Vǎlentina Castro",
        "¿Cuáles son las notas de E\u202ES\u2066T-002?"
    };

    public static TheoryData<string> PreguntasPropiasOExceptuadas => new()
    {
        "mi id es E S T 0 0 1, ¿cuál es mi promedio?",
