            linea => Assert.DoesNotMatch(@":\s*(ninguna|ninguno)?\s*\.?$", linea));
    }

    [Theory]
    [MemberData(nameof(EstudiantesSinPerdidas))]
    [Trait("CA", "CA-18")]
    [Trait("ESC", "ESC-189")]
