    [MemberData(nameof(ReportesDelProveedor))]
    [Trait("CA", "CA-23")]
    [Trait("ESC", "ESC-199")]
    [Trait("D", "D-57")]
    public async Task ESC_199e2e5_El_limite_el_uso_real_la_falta_de_usage_y_otro_proveedor_no_detectan_truncado(string caso, string? llave, int reporte, bool truncado)
